package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for TarUtils.parseName
 */
public class TarUtils_parseName_TriageGen2Test {

    @Test
    public void testParseName_NormalString() {
        byte[] buffer = "hello".getBytes();
        String result = TarUtils.parseName(buffer, 0, 5);
        assertEquals("hello", result);
    }

    @Test
    public void testParseName_WithNullTerminator() {
        // Test that it stops at the first null byte (0)
        byte[] buffer = {'a', 'b', 0, 'c', 'd'};
        String result = TarUtils.parseName(buffer, 0, 5);
        assertEquals("ab", result);
    }

    @Test
    public void testParseName_WithOffset() {
        // Test that it respects the offset parameter
        byte[] buffer = {'x', 'y', 'a', 'b', 'c', 'z'};
        String result = TarUtils.parseName(buffer, 2, 3);
        assertEquals("abc", result);
    }

    @Test
    public void testParseName_WithLimitedLength() {
        // Test that it respects the length parameter even if no null terminator is found
        byte[] buffer = {'a', 'b', 'c', 'd', 'e'};
        String result = TarUtils.parseName(buffer, 0, 3);
        assertEquals("abc", result);
    }

    @Test
    public void testParseName_EmptyLength() {
        byte[] buffer = {'a', 'b', 'c'};
        String result = TarUtils.parseName(buffer, 0, 0);
        assertEquals("", result);
    }

    @Test
    public void testParseName_NullByteAtStart() {
        byte[] buffer = {0, 'a', 'b'};
        String result = TarUtils.parseName(buffer, 0, 3);
        assertEquals("", result);
    }

    @Test
    public void testParseName_OffsetAtEnd() {
        byte[] buffer = {'a', 'b', 'c'};
        String result = TarUtils.parseName(buffer, 3, 0);
        assertEquals("", result);
    }

    @Test
    public void testParseName_FullBufferIsNull() {
        byte[] buffer = {0, 0, 0};
        String result = TarUtils.parseName(buffer, 0, 3);
        assertEquals("", result);
    }

    @Test
    public void testParseName_SingleCharacter() {
        byte[] buffer = {'Z'};
        String result = TarUtils.parseName(buffer, 0, 1);
        assertEquals("Z", result);
    }
}
